const cases = [
  ["stage3_krun_example", "listValue(1, 2, 3, 2, 4)"],
  ["stage3_krun_empty", "listValue()"],
  ["stage3_krun_singleton", "listValue(0)"],
  ["stage3_krun_twice", "listValue(0, 0)"],
  ["stage3_krun_thrice", "listValue(0, 0, 0)"],
  ["stage3_krun_negative", "listValue(-1, 0, -1, 2)"],
  ["stage3_krun_order", "listValue(1, 2, 3, 1, 4, 2, 5)"],
];
const results = await Promise.all(cases.map(async ([label, input]) => {
  const escapedInput = input.replaceAll("'", "'\\''");
  const cmd = `/audit-output/evidence/run_logged.sh ${label} krun solution.mpy --definition /tmp/audit-work/build/semantic-kompiled '-cINPUT=${escapedInput}'`;
  const result = await tools.exec_command({
    cmd,
    workdir: "/tmp/audit-work/candidate-src",
    yield_time_ms: 30000,
    max_output_tokens: 12000,
  });
  return {label, exit_code: result.exit_code, output: result.output};
}));
for (const result of results) {
  text(`${result.label}: exit=${result.exit_code}\n${result.output}`);
}
